import review from'./legacy-2017-pm5-review.json';
import assert from'node:assert/strict';
const decode=(s:string)=>s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#x27;/g,"'");
export function pm5SvgElements(svg:string,tag:string){return[...svg.matchAll(new RegExp('<'+tag+'\\b([^>]*)(?:>([\\s\\S]*?)</'+tag+'>|/?>)','g'))].map(m=>({attrs:Object.fromEntries([...m[1].matchAll(/([\w-]+)="([^"]*)"/g)].map(x=>[x[1],decode(x[2])])),text:decode(m[2]??'')}));}
export function readLegacy2017Pm5Figure(svg:string,figure:number,index=0){const rects=pm5SvgElements(svg,'rect'),paths=pm5SvgElements(svg,'path'),texts=pm5SvgElements(svg,'text'),nodes=new Map(rects.map(x=>[x.attrs['data-node'],x]));assert.equal((svg.match(/role="img"/g)??[]).length,1);assert(svg.includes('<title')&&svg.includes('<desc'));assert(svg.includes('aria-hidden="true"'));assert(!svg.includes('dangerouslySetInnerHTML'));
 if(figure===3){const band=nodes.get('source-omission-fullwidth-reference');assert(band);assert.deepEqual(['x','y','width','height'].map(k=>Number(band.attrs[k])),[20,229,950,30]);const dots=pm5SvgElements(svg,'circle').filter(x=>x.attrs['data-omission-dot']);assert.equal(dots.length,3);assert.deepEqual(dots.map(x=>Number(x.attrs.cx)),[495,495,495]);assert.deepEqual(dots.map(x=>Number(x.attrs.cy)),[236,244,252]);assert(!texts.some(t=>t.text==='…'));for(const r of rects){const a=r.attrs;if(a['data-node']==='screen'||a['data-node']==='source-omission-fullwidth-reference')continue;const x=Number(a.x),y=Number(a.y),h=Number(a.height);assert(!(x>20&&x<970&&y<259&&y+h>229),'column boundary through omission');}assert.equal(rects.filter(r=>/^screen-r[124]c/.test(r.attrs['data-node']??'')).length,27);}
 if(figure===6){assert(!nodes.has('testdata-r0c0'));const headers=rects.filter(r=>/^testdata-r0c/.test(r.attrs['data-node']??''));assert.equal(headers.length,7);assert(headers.every(r=>Number(r.attrs.x)>=145&&Number(r.attrs.y)===10));assert.equal(rects.filter(r=>/^testdata-r[1-6]c[0-7]$/.test(r.attrs['data-node']??'')).length,48);assert(!rects.some(r=>Number(r.attrs.x)===10&&Number(r.attrs.y)<56),'blank corner');assert(!paths.some(p=>/^M\s*10[ ,]+(?:10|[2-4]\d|5[0-5])(?=[^0-9.]|$)/.test(p.attrs.d??'')),'left border extends into missing corner');}
 if(figure===5){const blanks=rects.filter(r=>/-blank-[ab]$/.test(r.attrs['data-node']??''));assert.deepEqual(blanks.map(r=>r.attrs['data-node']).sort(),['a-left-blank-a','a-right-blank-a','capacity-blank-b']);for(const b of blanks){const x=Number(b.attrs.x),y=Number(b.attrs.y),w=Number(b.attrs.width),h=Number(b.attrs.height),inside=texts.filter(t=>Number(t.attrs.x)>x&&Number(t.attrs.x)<x+w&&Number(t.attrs.y)>y&&Number(t.attrs.y)<y+h);assert.equal(inside.length,1);assert.equal(inside[0].text,b.attrs['data-node'].endsWith('-a')?'a':'b');}assert.equal(paths.filter(p=>p.attrs['data-callout']).length,4);assert.equal(paths.filter(p=>p.attrs['data-edge']).length,24);assert(texts.some(t=>t.text==='i＞注文情報件数'));assert.equal(texts.filter(t=>['①','②','③','④'].includes(t.text)).length,4);}
 const source=review.cases[index].displayDocument.figures[figure-1],plain=(v:string)=>v.replace(/\s/g,''),group=(prefix:string)=>plain(texts.filter(t=>(t.attrs['data-text']??'').startsWith(prefix+'-')&&/^\d+$/.test((t.attrs['data-text']??'').slice(prefix.length+1))).map(t=>t.text).join('')),all=plain(texts.map(t=>t.text).join(''));
 if(figure===1)for(const[id,value]of[['purchaser','購買担当者'],['supplier','仕入先の営業員'],['register','発注登録'],['print','注文書出力'],['document','注文書'],['register-process','発注登録処理'],['print-process','注文書出力処理']])assert.equal(group(id),value);
 if(figure===2){assert('leftToRight'in source);source.leftToRight!.forEach((t,i)=>assert.equal(group('operation-'+i),plain(t)));}
 if(figure===3){assert('columns'in source&&'rows'in source);const rows=[source.columns!,source.rows![0],source.rows![1],source.rows!.at(-1)!];for(const[row,ri]of rows.map((row,i)=>[row,[0,1,2,4][i]]as const))row.forEach((cell,c)=>assert.equal(group('screen-r'+ri+'c'+c),plain(cell)));}
 if(figure===4){assert('firstRecord'in source);for(const[k,v]of Object.entries(source.firstRecord!)){if(k==='注文番号'||k==='注文枝番')continue;assert.equal(group(k==='購買担当者'?'first-person':'first-'+k),plain(v as string));}assert.equal(group('first-order'),source.firstRecord!.注文番号+source.firstRecord!.注文枝番);assert('maxRecordsBracket'in source);assert(all.includes(plain(source.maxRecordsBracket!)));for(const name of['customer','supplier']as const){assert(name in source);for(const value of source[name]!)assert(all.includes(plain(value)));}}
 if(figure===5){const expected:Record<string,string>={'start':'開始','init-work':'出力ワーク領域[][]の初期化','init-state':'ページ変数←1出力件数←1購買グループ名変数←注文データ[1].購買グループ名i←1ページカウントフラグ←0','loop-top':'出力ワーク領域の作成i＞注文情報件数','group':'購買グループ名変数＝注文データ[i].購買グループ名','group-update':'購買グループ名変数←注文データ[i].購買グループ名','page-left':'ページ変数←ページ変数＋1','flag-left':'ページカウントフラグ←0','write-left':'出力ワーク領域[ページ変数][出力件数]←注文データ[i]','increment-left':'出力件数←出力件数＋1','write-right':'出力ワーク領域[ページ変数][出力件数]←注文データ[i]','flag-one':'ページカウントフラグ←1','flag-zero-right':'ページカウントフラグ←0','page-right':'ページ変数←ページ変数＋1','increment-right':'出力件数←出力件数＋1','i-increment':'i←i＋1','loop-bottom':'出力ワーク領域の作成','end':'終了'};for(const[k,v]of Object.entries(expected))assert.equal(group(k),v,k+' source text');const note=review.sourceTranscription.paragraphs.find(p=>p.id==='figure5-note')!;assert(all.includes(plain(note.text!)));assert.equal(texts.filter(t=>t.text==='Yes').length,3);assert.equal(texts.filter(t=>t.text==='No').length,3);}
 if(figure===6){assert('columns'in source&&'rows'in source);source.columns!.slice(1).forEach((cell,c)=>assert.equal(group('testdata-r0c'+(c+1)),plain(cell)));source.rows!.forEach((row,r)=>row.forEach((cell,c)=>assert.equal(group('testdata-r'+(r+1)+'c'+c),plain(cell))));const note=review.sourceTranscription.paragraphs.find(p=>p.id==='figure6-note')!;assert(all.includes(plain(note.text!)));}
 return{figure,rectangles:rects.length,paths:paths.length,textNodes:texts.length,visibleText:texts.map(x=>x.text).join(''),notStructuralMetadata:true};
}
